// review evaluates a period as of today. Reference periods before the first
// activity are ignored, so a new installation is not compared with zeros.
func (s *server) review(ctx context.Context, p reviewPeriod, today time.Time, first time.Time) (reviewResult, error) {
	res := reviewResult{Period: p, Fraction: 1}
	to := p.To
	if tomorrow := today.AddDate(0, 0, 1); tomorrow.Before(to) {
		to = tomorrow
		res.Fraction = float64(tomorrow.Sub(p.From)) / float64(p.To.Sub(p.From))
	}
	start := p.From
	for _, r := range p.Refs {
		start = minTime(start, r[0])
	}
	health, err := s.Store.HealthDays(ctx, start, to.AddDate(0, 0, -1), []string{insight.Sleep, insight.RestingHR, insight.HRV})
	if err != nil {
		return res, err
	}
	loads, err := s.Store.DailyLoad(ctx, start, to)
	if err != nil {
		return res, err
	}
	zones, err := s.Store.ZoneTotals(ctx, store.ListFilter{From: start, To: to}, store.ZoneHR, store.ByDay)
	if err != nil {
		return res, err
	}
	figures := func(from, to time.Time) (insight.PeriodFigures, error) {
		var f insight.PeriodFigures
		t, err := s.Store.Totals(ctx, store.ListFilter{From: from, To: to})
		if err != nil {
			return f, err
		}
		f.Activities, f.DistanceM, f.TimerS = t.Count, t.DistanceM, t.TimerS
		for _, l := range loads {
			if !l.Date.Before(from) && l.Date.Before(to) {
				f.Load += l.Garmin
			}
		}
		for _, z := range zones {
			d, err := time.Parse(time.DateOnly, z.Key)
			if err != nil || d.Before(from) || !d.Before(to) {
				continue
			}
			switch {
			case z.Zone <= 0:
			case z.Zone <= 2:
				f.EasyS += z.Seconds
			case z.Zone == 3:
				f.ModerateS += z.Seconds
			default:
				f.HardS += z.Seconds
			}
		}
		var sleep, rhr, hrv []float64
		for _, d := range health {
			if d.Date.Before(from) || !d.Date.Before(to) {
				continue
			}
			for col, dst := range map[string]*[]float64{insight.Sleep: &sleep, insight.RestingHR: &rhr, insight.HRV: &hrv} {
				if v, ok := num(d.Values[col]); ok && v > 0 {
					*dst = append(*dst, v)
				}
			}
		}
		f.Sleep, f.RestingHR, f.HRV = avg(sleep), avg(rhr), avg(hrv)
		return f, nil
	}
	if res.Current, err = figures(p.From, to); err != nil {
		return res, err
	}
	var refs []insight.PeriodFigures
	for _, r := range p.Refs {
		if !first.IsZero() && r[1].Before(first) {
			continue
		}
		f, err := figures(r[0], r[1])
		if err != nil {
			return res, err
		}
		refs = append(refs, f)
	}
	if res.Records, err = s.Store.NewRecords(ctx, p.From, to); err != nil {
		return res, err
	}
	for _, r := range res.Records {
		res.Current.Records = append(res.Current.Records, recordLabel(r))
	}
	base := insight.Baseline(refs)
	res.HasBase = len(refs) > 0
	if res.HasBase {
		res.Statements = insight.Review(res.Current, base, res.Fraction, p.RefLabel)
	}
	scale := func(v float64) float64 { return v * res.Fraction }
	base.DistanceM, base.TimerS, base.Load = scale(base.DistanceM), scale(base.TimerS), scale(base.Load)
	base.Activities = int(scale(float64(base.Activities)) + 0.5)
	res.Baseline = base
	return res, nil
}

func avg(xs []float64) float64 {
	if len(xs) == 0 {
		return 0
	}
	sum := 0.0
	for _, x := range xs {
		sum += x
	}
	return sum / float64(len(xs))
}

func minTime(a, b time.Time) time.Time {
	if b.Before(a) {
		return b
	}
	return a
}

var groupLabels = map[string]string{analysis.GroupBike: "Rad", analysis.GroupRun: "Laufen", analysis.GroupHike: "Wandern"}

// recordLabel names an effort, e.g. "20 km Rad" or "5 min Leistung".
func recordLabel(r store.EffortRecord) string {
	if r.Kind == store.EffortPower {
		return analysis.DurationLabel(r.Key) + " Leistung"
	}
	return analysis.DistanceLabel(r.Key) + " " + groupLabels[r.Group]
}

// firstActivityDate is the local date of the oldest activity (zero if none).
func (s *server) firstActivityDate(ctx context.Context) (time.Time, error) {
	first, ok, err := s.Store.FirstLocalStart(ctx)
	if err != nil || !ok {
		return time.Time{}, err
	}
	return localDate(first), nil
}

