func (s *server) weekCard(ctx context.Context, today time.Time) (*weekCard, error) {
	first, err := s.firstActivityDate(ctx)
	if err != nil || first.IsZero() {
		return nil, err
	}
	day, title := today, "Diese Woche bisher"
	if today.Sub(weekStart(today)) < 2*24*time.Hour {
		day, title = today.AddDate(0, 0, -7), "Letzte Woche"
	}
	p := newReviewPeriod("week", day)
	res, err := s.review(ctx, p, today, first)
	if err != nil {
		return nil, err
	}
	return &weekCard{Title: title, Link: "review?unit=week&d=" + p.From.Format(time.DateOnly),
		Statements: res.Statements, RefLabel: p.RefLabel, HasBase: res.HasBase}, nil
}

