func (s *server) reviewPage(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	today := localDate(s.now())
	q := r.URL.Query()
	unit := "week"
	if q.Get("unit") == "month" {
		unit = "month"
	}
	day := today
	if d, err := time.Parse(time.DateOnly, q.Get("d")); err == nil && !d.After(today) {
		day = d
	}
	first, err := s.firstActivityDate(ctx)
	if err != nil {
		s.serverError(w, "first activity", err)
		return
	}
	p := newReviewPeriod(unit, day)
	res, err := s.review(ctx, p, today, first)
	if err != nil {
		s.serverError(w, "review", err)
		return
	}
	d := reviewData{Title: p.Title, Running: res.Fraction < 1, RefLabel: p.RefLabel, RefShort: p.RefShort, HasBase: res.HasBase, Statements: res.Statements,
		Early: res.Fraction < insight.MinFraction}
	for _, rec := range res.Records {
		v, _ := effortValue(rec.Effort)
		d.Records = append(d.Records, recordView{rec.ActivityID, recordLabel(rec), v, localTime(rec.StartTime, rec.TZOffsetS)})
	}
	for _, u := range []option{{"week", "Woche", false}, {"month", "Monat", false}} {
		u.Active = u.ID == unit
		d.Units = append(d.Units, u)
	}
	if prev := newReviewPeriod(unit, p.From.AddDate(0, 0, -1)); first.IsZero() || prev.To.After(first) {
		d.Prev = "review?unit=" + unit + "&d=" + prev.From.Format(time.DateOnly)
	}
	if !p.To.After(today) {
		d.Next = "review?unit=" + unit + "&d=" + p.To.Format(time.DateOnly)
	}
	c, b := res.Current, res.Baseline
	share := func(f insight.PeriodFigures, hard bool) string {
		v, ok := f.EasyShare()
		if hard {
			v, ok = f.HardShare()
		}
		if !ok {
			return "–"
		}
		return fmt.Sprintf("%.0f %%", 100*v)
	}
	opt := func(v float64, f func(float64) string) string {
		if v <= 0 {
			return "–"
		}
		return f(v)
	}
	d.Rows = []reviewRow{
		{"Aktivitäten", fmt.Sprint(c.Activities), fmt.Sprint(b.Activities)},
		{"Distanz", km(c.DistanceM) + " km", km(b.DistanceM) + " km"},
		{"Zeit", hours(c.TimerS) + " h", hours(b.TimerS) + " h"},
		{"Belastung", fmt.Sprintf("%.0f", c.Load), fmt.Sprintf("%.0f", b.Load)},
		{"Locker (Z1–2)", share(c, false), share(b, false)},
		{"Intensiv (Z4–5)", share(c, true), share(b, true)},
		{"Schlaf ⌀", opt(c.Sleep, hoursH), opt(b.Sleep, hoursH)},
		{"Ruhepuls ⌀", opt(c.RestingHR, bpm), opt(b.RestingHR, bpm)},
		{"HRV ⌀", opt(c.HRV, ms), opt(b.HRV, ms)},
	}
	s.render(w, r, "review.html", "stats", d)
}

func hoursH(v float64) string { return hours(v) + " h" }
func bpm(v float64) string    { return fmt.Sprintf("%.0f bpm", v) }
func ms(v float64) string     { return fmt.Sprintf("%.0f ms", v) }
